// Общие помощники для тестов «товар ↔ места склада» (#d17c625a, #7b8b97e9): товары QA-AUTO, свободные места «ריק»
// выбираются на карте во время прогона (коды не зашиты), привязка/приёмка/«הסרה מהמקום», уборка.
// Карта склада (раскладка) не меняется — только привязки товаров QA-AUTO к уже существующим пустым полкам.
import { test, expect, Page, Browser, Locator } from '@playwright/test';
import * as path from 'path';

export const ADMIN = path.resolve(__dirname, '../../../auth/admin.json');
export const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
export const NO_PLACE = 'ללא מקום — לשיוך בהמשך';
export const FLOOR = 'קומה 1';

export type Place = { code: string; shelf: string; cabinet: string };

// ---------- каталог ----------
export const qtyBtn = (page: Page, p: string) => page.getByRole('button', { name: `קליטת מלאי — ${p}`, exact: true });
export const locBtn = (page: Page, p: string) => page.getByRole('button', { name: `מיקום במחסן — ${p}`, exact: true });
export const row = (page: Page, p: string) => qtyBtn(page, p).locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');

export async function findProduct(page: Page, p: string) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(p);
  await expect(qtyBtn(page, p).or(page.getByText('לא נמצאו מוצרים התואמים לסינון'))).toBeVisible({ timeout: 20_000 });
}

export async function expectStock(page: Page, p: string, n: number) {
  await findProduct(page, p);
  await expect(qtyBtn(page, p)).toHaveText(String(n), { timeout: 15_000 });
}

/** Новый товар QA-AUTO (цена по умолчанию 1); имя сразу попадает в `created` — для уборки даже при падении на сохранении. */
export async function createProduct(page: Page, p: string, sku: string, created: Set<string>, price = '1') {
  await page.goto('/catalog/new');
  await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /שם מוצר/ }).fill(p);
  await page.getByRole('textbox', { name: /מק"ט/ }).fill(sku);
  await page.getByRole('spinbutton', { name: 'מחיר בסיס' }).fill(price);
  created.add(p);
  await page.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(page.getByText('נוסף לקטלוג.')).toBeVisible({ timeout: 15_000 });
}

/** id товара (uuid) — из ссылки на форму редактирования. */
export async function productId(page: Page, p: string): Promise<string> {
  await findProduct(page, p);
  await page.getByRole('button', { name: p, exact: true }).click();
  await expect(page).toHaveURL(/\/edit$/);
  return page.url().match(/catalog\/([0-9a-f-]{36})\/edit/)![1];
}

// ---------- карта склада ----------
export const side = (page: Page) =>
  page.getByRole('complementary').filter({ has: page.getByRole('button', { name: 'כיווץ סרגל האחסון' }) });

export async function openMap(page: Page) {
  await page.goto('/warehouse/map');
  await expect(page.getByRole('heading', { level: 1, name: 'מפת המחסן' })).toBeVisible({ timeout: 30_000 });
  const tabs = page.getByRole('tablist', { name: 'קומות המחסן' });
  await expect(tabs).toBeVisible({ timeout: 30_000 });
  await tabs.getByRole('tab', { name: FLOOR }).click();
  await expect(page.getByText('טוען את המלאי')).toHaveCount(0, { timeout: 30_000 });
}

/** Полки шкафа на «קומה 1»: подпись кнопки — «<имя>\n<код>\n<ריק|…>». */
async function cabinetShelves(page: Page, cabinet: string) {
  await openMap(page);
  await side(page).getByRole('button', { name: new RegExp(`^ארון ${cabinet}\\b`) }).click();
  await expect(side(page).getByRole('heading', { name: 'תכולת הארון' })).toBeVisible();
  const texts = await side(page).getByRole('button').allInnerTexts();
  return texts
    .map((t) => t.split('\n').map((s) => s.trim()).filter(Boolean))
    .filter((l) => l.length >= 3 && new RegExp(`^${cabinet}-\\d+$`).test(l[1]))
    .map((l) => ({ shelf: l[0], code: l[1], empty: l[l.length - 1] === 'ריק' }));
}

/**
 * n свободных («ריק») полок из шкафов `cabinets` по порядку. Имя полки должно быть уникальным в шкафу
 * (по нему выбираем в окне «מיקום במחסן»). Мало пустых — test.skip (тест не занимает чужие места).
 */
export async function pickEmptyPlaces(page: Page, n: number, cabinets: string[]): Promise<Place[]> {
  const out: Place[] = [];
  for (const cabinet of cabinets) {
    const shelves = await cabinetShelves(page, cabinet);
    for (const s of shelves) {
      if (!s.empty || shelves.filter((x) => x.shelf === s.shelf).length > 1) continue;
      out.push({ code: s.code, shelf: s.shelf, cabinet });
      if (out.length === n) return out;
    }
  }
  test.skip(true, `нет ${n} пустых мест в шкафах ${cabinets.join(', ')} (найдено ${out.length})`);
  return out;
}

/** Открыть полку на карте (панель «תכולת המדף»). Возвращает подпись кнопки полки. */
export async function openPlace(page: Page, place: Place): Promise<string[]> {
  await openMap(page);
  await side(page).getByRole('button', { name: new RegExp(`^ארון ${place.cabinet}\\b`) }).click();
  await expect(side(page).getByRole('heading', { name: 'תכולת הארון' })).toBeVisible();
  const shelf = side(page).getByRole('button', { name: new RegExp(`${place.code}(?!\\d)`) }).first();
  await expect(shelf).toBeVisible();
  const label = (await shelf.innerText()).split('\n').map((s) => s.trim()).filter(Boolean);
  await shelf.click();
  await expect(side(page).getByRole('heading', { name: 'תכולת המדף' })).toBeVisible();
  return label;
}

/** Строка товара в панели места, закреплённая за местом (с «הסרה מהמקום»). */
export const placedItem = (page: Page, p: string) =>
  side(page).getByRole('listitem').filter({ hasText: p }).filter({ has: page.getByRole('button', { name: 'הסרה מהמקום' }) });

export async function qtyInPlacePanel(page: Page, p: string): Promise<number> {
  const item = placedItem(page, p);
  await expect(item).toHaveCount(1, { timeout: 15_000 });
  const n = (await item.innerText()).split('\n').map((s) => s.trim()).find((l) => /^\d+$/.test(l));
  return n === undefined ? NaN : Number(n);
}

/** «הסרה מהמקום» → «הסרה» у товара в открытой панели места. strict — проверить текст подтверждения. */
export async function unplaceInPanel(page: Page, p: string, strict = false) {
  const item = placedItem(page, p);
  await expect(item).toHaveCount(1, { timeout: 20_000 });
  await item.getByRole('button', { name: 'הסרה מהמקום' }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'הסרת המוצר מהמקום' })).toBeVisible();
  if (strict) {
    await expect(dlg).toContainText(`להסיר את «${p}» ממקום זה?`);
    await expect(dlg).toContainText('המוצר יישאר במלאי, ללא מקום במחסן.');
  }
  await dlg.getByRole('button', { name: 'הסרה', exact: true }).click();
  await expect(placedItem(page, p)).toHaveCount(0, { timeout: 15_000 });
}

// ---------- привязка и приёмка ----------
/** Окно «מיקום במחסן» (первое место) или «הוספת מיקום» (add=true) → «קומה 1» → шкаф → полка → «שמירה». */
export async function bindPlace(page: Page, p: string, place: Place, add = false) {
  await findProduct(page, p);
  if (add) await row(page, p).getByText('הוספת מיקום').click();
  else await locBtn(page, p).first().click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: add ? 'הוספת מיקום' : 'מיקום במחסן' })).toBeVisible();
  await dlg.getByRole('tab', { name: FLOOR }).click();
  await expect(dlg.getByText('בחרו פריט אחסון')).toBeVisible();
  await dlg.getByRole('button', { name: `ארון ${place.cabinet}`, exact: true }).click();
  await expect(dlg.getByText(`בחרו מדף ב«ארון ${place.cabinet}»`)).toBeVisible();
  await dlg.getByRole('button', { name: place.shelf, exact: true }).click();
  await expect(dlg).toContainText(`| ${place.code}`);
  await dlg.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
}

/** Подпись опции «מקום היעד» для места (содержит «(<код>)»). */
export async function placeOption(dlg: Locator, code: string) {
  const texts = await dlg.getByRole('combobox', { name: 'מקום היעד' }).locator('option').allInnerTexts();
  const hit = texts.filter((t) => t.includes(`(${code})`));
  expect(hit, `опция места ${code}`).toHaveLength(1);
  return hit[0];
}

/** «קליטת מלאי» (число «במלאי») → место code (null = «ללא מקום») → кол-во → «הוספה». */
export async function receive(page: Page, p: string, qty: number, code: string | null) {
  await findProduct(page, p);
  const before = Number((await qtyBtn(page, p).innerText()).trim()) || 0;
  await qtyBtn(page, p).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
  const select = dlg.getByRole('combobox', { name: 'מקום היעד' });
  await select.selectOption({ label: code ? await placeOption(dlg, code) : NO_PLACE });
  await dlg.getByRole('spinbutton', { name: 'כמות', exact: true }).fill(String(qty));
  await dlg.getByRole('button', { name: 'הוספה' }).click();
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
  await expectStock(page, p, before + qty);
}

// ---------- удаление ----------
export const BLOCK = 'לא ניתן למחוק מוצר עם מלאי';

/** ⋮ → пункт «מחיקה…» (возвращает пункт меню, не нажимая). */
export async function openRowMenuDelete(page: Page, p: string) {
  await row(page, p).getByRole('button', { name: 'פעולות' }).click();
  const del = page.getByRole('menuitem', { name: /^מחיקה/ });
  await expect(del).toBeVisible();
  return del;
}

/** Обычное окно «מחיקת מוצר» (#d17c625a, решение 11.10). */
export async function expectPlainDeleteDialog(dlg: Locator, p: string) {
  await expect(dlg.getByRole('heading', { name: 'מחיקת מוצר' })).toBeVisible({ timeout: 20_000 });
  await expect(dlg.getByRole('heading', { name: BLOCK })).toHaveCount(0);
  // имя в bidi-изоляторах U+2068/U+2069: «האם למחוק את ⁨"<p>"⁩?»
  await expect(dlg).toContainText(new RegExp(`האם למחוק את \\W?"${p}"\\W?\\?`));
  await expect(dlg).toContainText('הפעולה אינה ניתנת לביטול.');
  await expect(dlg).not.toContainText('ייגרעו');
  await expect(dlg).not.toContainText('החזרה לספק');
  await expect(dlg.getByRole('button', { name: 'ביטול' })).toBeVisible();
  await expect(dlg.getByRole('button', { name: 'מחיקה', exact: true })).toBeVisible();
}

/**
 * «מחיקה» в обычном окне → rpc/delete_product 200 → тост → товара нет в каталоге.
 * Без движений — «"<p>" נמחק.»; товар с движениями в יומן תנועות уходит в архив — «"<p>" הוסר מהקטלוג. …נשמרו.»
 */
export async function confirmDelete(page: Page, p: string, withHistory = false) {
  const dlg = page.getByRole('dialog');
  const respP = page.waitForResponse((r) => r.url().includes('/rpc/delete_product') && r.request().method() === 'POST');
  await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
  const resp = await respP;
  expect(resp.status(), `delete_product: ${await resp.text().catch(() => '')}`).toBe(200);
  const text = withHistory ? /הוסר מהקטלוג\. ההזמנות והתנועות שמזכירות אותו נשמרו\./ : /נמחק\./;
  await expect(page.getByText(text).filter({ hasText: p }).first()).toBeVisible({ timeout: 15_000 });
  await findProduct(page, p);
  await expect(qtyBtn(page, p)).toHaveCount(0);
}

// ---------- уборка ----------
/** Учёт для уборки: товар → места, к которым тест его привязывал. */
export type Used = Map<string, Place[]>;
export function track(used: Used, p: string, ...places: Place[]) {
  used.set(p, [...(used.get(p) ?? []), ...places]);
}

/**
 * Для каждого товара: «הסרה מהמקום» в его местах (остаток остаётся «ללא מקום» — без новых списаний),
 * затем удаление обычным окном (не привязан → удаляется сразу, #d17c625a). Все места снова «ריק».
 */
export async function cleanup(browser: Browser, created: Set<string>, used: Used) {
  const ctx = await browser.newContext({ storageState: ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  try {
    for (const p of created) {
      await findProduct(page, p);
      if (!(await qtyBtn(page, p).count())) continue;
      for (const place of used.get(p) ?? []) {
        await openPlace(page, place);
        if (await placedItem(page, p).count()) await unplaceInPanel(page, p);
      }
      await findProduct(page, p);
      await (await openRowMenuDelete(page, p)).click();
      const dlg = page.getByRole('dialog');
      await expect(dlg.getByRole('heading', { name: 'מחיקת מוצר' })).toBeVisible({ timeout: 20_000 });
      await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
      await expect(page.getByText(/נמחק\.|הוסר מהקטלוג/).first()).toBeVisible({ timeout: 15_000 });
    }
    const all = new Map<string, Place>();
    for (const list of used.values()) for (const pl of list) all.set(pl.code, pl);
    for (const place of all.values()) {
      const label = await openPlace(page, place);
      expect(label[label.length - 1], `${place.code} должно быть «ריק» после уборки`).toBe('ריק');
    }
  } finally {
    await ctx.close();
  }
}
